class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        count = {}
        ans = []
        for i in range(len(nums)):
            id = nums[i]
            f = freq[i]
            if id in count:
                count[id] += f
            else:
                count[id] = f
            # remove id if count is 0
            if count[id] == 0:
                del count[id]
            if count:
                ans.append(max(count.values()))
